    // §27.9: this file covers 155 operations, 117 models (117 of them also through their
    // memberwise initializer) and 23 enums.
    //
    // The counts above are literals THIS generator wrote, so comparing them to each other would
    // be a tautology a bad regeneration still satisfies. They are compared against the vendored
    // registry instead, read at run time: if the registry gains an operation and nobody
    // regenerates, the literal is stale and this fails — which is the same thing CI's
    // drift-check job catches, asserted from inside the suite so it is also true for anyone
    // running `swift test` locally.
    func testCoverageMatchesTheVendoredRegistry() throws {
        let root = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()  // AxiamSDKTests
            .deletingLastPathComponent()  // Tests
            .deletingLastPathComponent()  // repository root
        let data = try Data(contentsOf: root.appendingPathComponent("management-registry.json"))
        let registry = try XCTUnwrap(
            JSONSerialization.jsonObject(with: data) as? [String: Any])
        let namespaces = try XCTUnwrap(registry["namespaces"] as? [String: [String: Any]])

        let declared = namespaces.values.reduce(into: 0) { total, namespace in
            total += (namespace["operations"] as? [String: Any])?.count ?? 0
        }
        XCTAssertEqual(declared, 155,
                       "the registry declares a different number of operations than this file covers — regenerate with Scripts/gen_management.py")
        XCTAssertEqual(namespaces.count, 24)
    }
